mapper.select:
select r.id, r.file_id, f.original_name as file_name, r.title, r.stance, r.status, r.risk_level, case when r.risks_json is null or r.risks_json = '' then 0 else JSON_LENGTH(r.risks_json) end as risk_count, r.create_time, r.update_time from law_contract_review r left join law_private_file f on f.id = r.file_id where r.user_id = #{userId}
and r.status = #{query.status}
and r.risk_level = #{query.riskLevel}
and r.title like concat('%', #{query.title}, '%')
order by r.id desc

mapper.insert:
insert into law_contract_review (
    user_id, file_id, title, stance, contract_text, status, risk_level, summary,
    risks_json, model_name, error_msg, create_time, update_time
) values (
    #{userId}, #{fileId}, #{title}, #{stance}, #{contractText}, #{status}, #{riskLevel}, #{summary},
    #{risksJson}, #{modelName}, #{errorMsg}, #{createTime}, #{updateTime}
)

mapper.update:
update law_contract_review
set status     = 'failed',
    error_msg  = '审查超时，请重新发起',
    update_time = #{now}
where user_id = #{userId}
  and status = 'pending'
  and create_time < #{deadline}
